   Variables & Reset
   ========================================== */
:root {
    --primary-dark: #0f0f0f;
    --secondary-dark: #1a1a1a;
    --tertiary-dark: #2a2a2a;
    --accent-gold: #d4af37;
    --accent-light: #f5f5f5;
    --text-primary: #ffffff;
    --text-secondary: #b3b3b3;
    --border-color: #333333;
    --success: #4ade80;
    --transition: 0.3s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
    background-color: var(--primary-dark);
    color: var(--text-primary);
    line-height: 1.6;
}

/* ==========================================
   Header & Navigation
   ========================================== */
.header {
    background-color: var(--secondary-dark);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo h1 {
    font-size: 1.5rem;
    letter-spacing: 3px;
    font-weight: 700;
    background: linear-gradient(135deg, var(--accent-gold), #f5d547);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.nav {
    display: flex;
    gap: 2rem;
    align-items: center;
}

.nav a {
    color: var(--text-secondary);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    transition: color var(--transition);
    position: relative;
}

.nav a:hover {
    color: var(--accent-gold);
}

.nav a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--accent-gold);
    transition: width var(--transition);
}

.nav a:hover::after {
    width: 100%;
}

.cart-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.cart-icon svg {
    transition: transform var(--transition);
}

.cart-icon:hover svg {
    transform: scale(1.1);
}

/* ==========================================
   Hero Section
   ========================================== */
.hero {
    height: 60vh;
    background: linear-gradient(135deg, var(--secondary-dark) 0%, var(--tertiary-dark) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(212, 175, 55, 0.1) 0%, transparent 70%);
    border-radius: 50%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 600px;
    padding: 0 2rem;
}

.hero h2 {
    font-size: 3.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    letter-spacing: -1px;
    line-height: 1.2;
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.cta-button {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    border: none;
    padding: 0.875rem 2.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 0;
    cursor: pointer;
    transition: all var(--transition);
    letter-spacing: 1px;
    text-transform: uppercase;
}

.cta-button:hover {
    background-color: #f5d547;
    transform: translateY(-2px);
    box-shadow: 0 10px 30px rgba(212, 175, 55, 0.2);
}

/* ==========================================
   Section Headers
   ========================================== */
.section-header {
    text-align: center;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
    font-weight: 700;
}

.section-header p {
    font-size: 1.1rem;
    color: var(--text-secondary);
}

/* ==========================================
   Products Section
   ========================================== */
.products-section {
    max-width: 1200px;
    margin: 0 auto;
    padding: 5rem 2rem;
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--secondary-dark);
    border: 1px solid var(--border-color);
