    border-radius: 0;
}

.badge.new {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
}

.badge.sale {
    background-color: #ef4444;
    color: white;
}

.product-info {
    padding: 1.5rem;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.4rem;
    font-weight: 600;
}

.category {
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.rating {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.stars {
    color: var(--accent-gold);
    letter-spacing: 2px;
}

.review-count {
    color: var(--text-secondary);
}

.price-section {
    display: flex;
