    --tertiary-dark: #2a2a2a;
    --accent-gold: #d4af37;
    --accent-light: #f5f5f5;
    --text-primary: #ffffff;
    --text-secondary: #b3b3b3;
    --border-color: #333333;
    --success: #4ade80;
    --transition: 0.3s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
    background-color: var(--primary-dark);
    color: var(--text-primary);
    line-height: 1.6;
}

/* ==========================================
   Header & Navigation
   ========================================== */
.header {
    background-color: var(--secondary-dark);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo h1 {
    font-size: 1.5rem;
    letter-spacing: 3px;
    font-weight: 700;
    background: linear-gradient(135deg, var(--accent-gold), #f5d547);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.nav {
    display: flex;
    gap: 2rem;
    align-items: center;
}

.nav a {
    color: var(--text-secondary);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    transition: color var(--transition);
    position: relative;
}

.nav a:hover {
    color: var(--accent-gold);
}

.nav a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--accent-gold);
    transition: width var(--transition);
}

.nav a:hover::after {
    width: 100%;
}

.cart-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.cart-icon svg {
    transition: transform var(--transition);
}

.cart-icon:hover svg {
    transform: scale(1.1);
}

/* ==========================================
   Hero Section
   ========================================== */
.hero {
    height: 60vh;
    background: linear-gradient(135deg, var(--secondary-dark) 0%, var(--tertiary-dark) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    position: relative;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(212, 175, 55, 0.1) 0%, transparent 70%);
    border-radius: 50%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 600px;
    padding: 0 2rem;
}

.hero h2 {
    font-size: 3.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
    letter-spacing: -1px;
    line-height: 1.2;
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.cta-button {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    border: none;
    padding: 0.875rem 2.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 0;
    cursor: pointer;
    transition: all var(--transition);
    letter-spacing: 1px;
    text-transform: uppercase;
}

.cta-button:hover {
    background-color: #f5d547;
    transform: translateY(-2px);
    box-shadow: 0 10px 30px rgba(212, 175, 55, 0.2);
}

/* ==========================================
   Section Headers
   ========================================== */
.section-header {
    text-align: center;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
    font-weight: 700;
}

.section-header p {
    font-size: 1.1rem;
    color: var(--text-secondary);
}

/* ==========================================
   Products Section
   ========================================== */
.products-section {
    max-width: 1200px;
    margin: 0 auto;
    padding: 5rem 2rem;
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--secondary-dark);
    border: 1px solid var(--border-color);
    transition: all var(--transition);
    cursor: pointer;
    overflow: hidden;
}

.product-card:hover {
    border-color: var(--accent-gold);
    box-shadow: 0 15px 40px rgba(212, 175, 55, 0.15);
    transform: translateY(-8px);
}

.product-image {
    position: relative;
    height: 280px;
    background-color: var(--tertiary-dark);
    overflow: hidden;
}

.image-placeholder {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, var(--tertiary-dark), var(--secondary-dark));
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
}

.badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    padding: 0.4rem 0.9rem;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border-radius: 0;
}

.badge.new {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
}

.badge.sale {
    background-color: #ef4444;
    color: white;
}

.product-info {
    padding: 1.5rem;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.4rem;
    font-weight: 600;
}

.category {
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.rating {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.stars {
    color: var(--accent-gold);
    letter-spacing: 2px;
}

.review-count {
    color: var(--text-secondary);
}

.price-section {
    display: flex;
    align-items: center;
    gap: 0.8rem;
    margin-bottom: 1rem;
}

.price {
    font-size: 1.4rem;
    font-weight: 700;
    color: var(--accent-gold);
}

.price-original {
    font-size: 0.95rem;
    color: var(--text-secondary);
    text-decoration: line-through;
}

.add-to-cart {
    width: 100%;
    padding: 0.75rem;
    background-color: var(--tertiary-dark);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    cursor: pointer;
    font-weight: 600;
    transition: all var(--transition);
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 0.5px;
}

.add-to-cart:hover {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    border-color: var(--accent-gold);
}

/* ==========================================
   Deals Section
   ========================================== */
.deals-section {
    max-width: 1200px;
    margin: 0 auto;
    padding: 5rem 2rem;
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.deal-card {
    height: 300px;
    background: linear-gradient(135deg, var(--secondary-dark), var(--tertiary-dark));
    border: 1px solid var(--border-color);
    position: relative;
    overflow: hidden;
    cursor: pointer;
    transition: all var(--transition);
}

.deal-card.large {
    grid-column: 1 / 2;
    height: 400px;
}

.deal-card:hover {
    border-color: var(--accent-gold);
    box-shadow: 0 15px 40px rgba(212, 175, 55, 0.2);
    transform: translateY(-5px);
}

.deal-overlay {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, rgba(15, 15, 15, 0.7), rgba(42, 42, 42, 0.7));
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all var(--transition);
}

.deal-card:hover .deal-overlay {
    background: linear-gradient(135deg, rgba(15, 15, 15, 0.5), rgba(42, 42, 42, 0.5));
}

.deal-content {
    text-align: center;
    z-index: 2;
    padding: 2rem;
}

.discount-badge {
    display: inline-block;
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    padding: 0.6rem 1.2rem;
    font-size: 0.9rem;
    font-weight: 700;
    margin-bottom: 1rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.deal-content h3 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.deal-content p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    font-size: 0.95rem;
}

.deal-button {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    border: none;
    padding: 0.75rem 2rem;
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-size: 0.9rem;
}

.deal-button:hover {
    background-color: #f5d547;
    transform: scale(1.05);
}

/* ==========================================
   Editorial Section
   ========================================== */
.editorial-section {
    max-width: 1200px;
    margin: 0 auto;
    padding: 5rem 2rem;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background-color: var(--secondary-dark);
    border: 1px solid var(--border-color);
    transition: all var(--transition);
    cursor: pointer;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.editorial-card.featured {
    grid-column: span 2;
}

.editorial-card:hover {
    border-color: var(--accent-gold);
    box-shadow: 0 15px 40px rgba(212, 175, 55, 0.15);
    transform: translateY(-8px);
}

.editorial-image {
    width: 100%;
    height: 250px;
    background: linear-gradient(135deg, var(--tertiary-dark), var(--secondary-dark));
    overflow: hidden;
}

.editorial-card.featured .editorial-image {
    height: 350px;
}

.editorial-content {
    padding: 2rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.tag {
    display: inline-block;
    background-color: var(--tertiary-dark);
    color: var(--accent-gold);
    padding: 0.4rem 0.9rem;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 1rem;
    width: fit-content;
    border-radius: 0;
    border: 1px solid var(--border-color);
}

.editorial-content h3 {
    font-size: 1.4rem;
    margin-bottom: 1rem;
    line-height: 1.3;
}

.editorial-card.featured .editorial-content h3 {
    font-size: 2rem;
}

.editorial-content p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    flex-grow: 1;
}

.article-meta {
    display: flex;
    gap: 1.5rem;
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 1rem;
}

.read-more {
    color: var(--accent-gold);
    text-decoration: none;
    font-weight: 600;
    transition: all var(--transition);
    display: inline-block;
}

.read-more:hover {
    transform: translateX(4px);
}

/* ==========================================
   Newsletter Section
   ========================================== */
.newsletter-section {
    background: linear-gradient(135deg, var(--secondary-dark), var(--tertiary-dark));
    padding: 4rem 2rem;
    margin: 3rem 0;
}

.newsletter-content {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter-content h2 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.newsletter-content > p:first-of-type {
    color: var(--text-secondary);
    margin-bottom: 2rem;
    font-size: 1.05rem;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.9rem 1.2rem;
    background-color: var(--secondary-dark);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    font-size: 1rem;
    transition: all var(--transition);
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent-gold);
    box-shadow: 0 0 0 3px rgba(212, 175, 55, 0.1);
}

.newsletter-form input::placeholder {
    color: var(--text-secondary);
}

.submit-button {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    border: none;
    padding: 0.9rem 2rem;
    font-weight: 700;
    cursor: pointer;
    transition: all var(--transition);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-size: 0.95rem;
}

.submit-button:hover {
    background-color: #f5d547;
    transform: translateY(-2px);
}

.form-note {
    font-size: 0.85rem;
    color: var(--text-secondary);
}

/* ==========================================
   Footer
   ========================================== */
.footer {
    background-color: var(--secondary-dark);
    border-top: 1px solid var(--border-color);
    padding: 3rem 2rem 2rem;
    margin-top: 5rem;
}

.footer-content {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 3rem;
}

.footer-section h4 {
    font-size: 0.95rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 1.5rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: 0.8rem;
}

.footer-section a {
    color: var(--text-secondary);
    text-decoration: none;
    font-size: 0.9rem;
    transition: color var(--transition);
}

.footer-section a:hover {
    color: var(--accent-gold);
}

.footer-bottom {
    max-width: 1200px;
    margin: 0 auto;
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* ==========================================
   Toast Notification
   ========================================== */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    background-color: var(--tertiary-dark);
    color: var(--text-primary);
    padding: 1rem 1.5rem;
    border-left: 4px solid var(--accent-gold);
    border-radius: 0;
    box-shadow: 0 5px 20px rgba(0, 0, 0, 0.5);
    opacity: 0;
    transform: translateX(400px);
    transition: all var(--transition);
    z-index: 1000;
}

.toast.show {
    opacity: 1;
    transform: translateX(0);
}

.toast.success {
    border-left-color: var(--success);
}

/* ==========================================
   Responsive Design
   ========================================== */
@media (max-width: 768px) {
    .header-container {
        padding: 1rem;
    }

    .nav {
        gap: 1rem;
    }

    .nav a {
        font-size: 0.85rem;
    }

    .hero h2 {
        font-size: 2.5rem;
    }

    .hero p {
        font-size: 1rem;
    }

    .section-header h2 {
        font-size: 2rem;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 1.5rem;
    }

    .editorial-card.featured {
        grid-column: span 1;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .toast {
        bottom: 1rem;
        right: 1rem;
        left: 1rem;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .deal-card.large {
        grid-column: 1 / 2;
    }
}

@media (max-width: 480px) {
    .logo h1 {
        font-size: 1.2rem;
    }

    .nav {
        gap: 0.8rem;
    }

    .hero {
        height: 50vh;
    }

    .hero h2 {
        font-size: 2rem;
    }

    .hero p {
        font-size: 0.95rem;
    }

    .cta-button {
        padding: 0.75rem 2rem;
        font-size: 0.9rem;
    }

    .section-header h2 {
        font-size: 1.5rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .product-image {
        height: 200px;
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }
}

// Initialize cart count
let cartCount = 0;

// Toast notification function
function showToast(message, type = 'success') {
    const toast = document.getElementById('toast');
    toast.textContent = message;
    toast.className = `toast ${type} show`;

    setTimeout(() => {
        toast.classList.remove('show');
    }, 3000);
}

// Add to cart functionality
document.querySelectorAll('.add-to-cart').forEach(button => {
    button.addEventListener('click', function(e) {
        e.preventDefault();
        const productCard = this.closest('.product-card');
        const productName = productCard.querySelector('h3').textContent;

        cartCount++;
        showToast(`${productName} added to cart!`, 'success');

        // Animate cart icon
        const cartIcon = document.querySelector('.cart-icon svg');
        cartIcon.style.animation = 'none';
        setTimeout(() => {
            cartIcon.style.animation = 'pulse 0.6s ease';
        }, 10);
    });
});

// Newsletter form submission
function handleNewsletterSubmit(e) {
    e.preventDefault();
    const email = e.target.querySelector('input[type="email"]').value;

    if (email) {
        showToast('Thank you for subscribing!', 'success');
        e.target.reset();
    }
}

// Cart icon click
document.querySelector('.cart-icon').addEventListener('click', function() {
    if (cartCount === 0) {
        showToast('Your cart is empty', 'info');
    } else {
        showToast(`You have ${cartCount} item${cartCount !== 1 ? 's' : ''} in your cart`, 'success');
    }
});

// Deal button click handlers
document.querySelectorAll('.deal-button').forEach(button => {
    button.addEventListener('click', function() {
        showToast('Exploring deals...', 'success');
    });
});

// Article link handlers
document.querySelectorAll('.read-more').forEach(link => {
    link.addEventListener('click', function(e) {
        e.preventDefault();
        const articleTitle = this.closest('.editorial-card').querySelector('h3').textContent;
        showToast(`Opening article: ${articleTitle}`, 'success');
    });
});

// Smooth scroll enhancement for mobile
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        if (href !== '#' && !href.includes('read-more')) {
            e.preventDefault();
            const target = document.querySelector(href);
            if (target) {
                target.scrollIntoView({
                    behavior: 'smooth',
                    block: 'start'
                });
            }
        }
    });
});

// Product card hover animation (desktop only)
if (window.innerWidth > 768) {
    document.querySelectorAll('.product-card').forEach(card => {
        card.addEventListener('mouseenter', function() {
            this.style.transform = 'translateY(-8px)';
        });

        card.addEventListener('mouseleave', function() {
            this.style.transform = 'translateY(0)';
        });
    });
}

// Intersection Observer for fade-in animations
const observerOptions = {
    threshold: 0.1,
    rootMargin: '0px 0px -100px 0px'
};

const observer = new IntersectionObserver(function(entries) {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.style.animation = 'fadeInUp 0.6s ease forwards';
            observer.unobserve(entry.target);
        }
    });
}, observerOptions);

// Observe product cards and editorial cards
document.querySelectorAll('.product-card, .editorial-card, .deal-card').forEach(el => {
    el.style.opacity = '0';
    observer.observe(el);
});

// Add animation keyframes dynamically
const style = document.createElement('style');
style.textContent = `
    @keyframes fadeInUp {
        from {
            opacity: 0;
            transform: translateY(30px);
        }
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }

    @keyframes pulse {
        0%, 100% {
            transform: scale(1);
        }
        50% {
            transform: scale(1.1);
        }
    }
`;
document.head.appendChild(style);

// Handle window resize for responsive behavior
let resizeTimer;
window.addEventListener('resize', function() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function() {
        // Reset animations on resize
        document.querySelectorAll('.product-card').forEach(card => {
            card.style.animation = '';
        });
    }, 250);
});

// Keyboard accessibility for buttons
document.querySelectorAll('button, a').forEach(element => {
    element.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' && this.tagName === 'A') {
            this.click();
        }
    });
});

// Log page ready state
console.log('Luxe Retail home page loaded successfully!');

